      outlook:"政策要因は2027年4月の施行まで続く中期テーマで、実需の受注につながるかが焦点。ただし時価総額43億円の小型株で1日に21.8%高、出来高は発行済株式数の約38%に相当する短期過熱。27年3月期は売上50億3,000万円（+71.8%）・営業益3億8,000万円への黒字転換計画で1Q営業益3億100万円と進捗は良好。次のカタリストは11月13日の2Q決算と追加受注の開示。"
